import{_ as o,o as t,c as r,a5 as a}from"./chunks/framework.DJo0M80U.js";const l=JSON.parse('{"title":"组件内的守卫","description":"最后，你可以在路由组件内直接定义路由导航守卫(传递给路由配置的) 可用的配置 API 你可以为路由组件添加以下配置： beforeRouteEnter beforeRouteUpdate beforeRouteLeave const UserDetails \\\\{ template。","frontmatter":{"title":"组件内的守卫","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","路由与状态管理"],"description":"最后，你可以在路由组件内直接定义路由导航守卫(传递给路由配置的) 可用的配置 API 你可以为路由组件添加以下配置： beforeRouteEnter beforeRouteUpdate beforeRouteLeave const UserDetails \\\\{ template。","sidebarWeight":44,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/vueRouter/导航守卫/组件内的守卫.md"},"headers":[],"relativePath":"posts/Vue系统教程/04-路由与状态管理/导航守卫/组件内的守卫.md","filePath":"posts/Vue系统教程/04-路由与状态管理/导航守卫/组件内的守卫.md"}'),s={name:"posts/Vue系统教程/04-路由与状态管理/导航守卫/组件内的守卫.md"};function d(n,e,c,u,f,i){return t(),r("div",null,[...e[0]||(e[0]=[a('<div><h1 id="组件内的守卫" tabindex="-1">组件内的守卫 <a class="header-anchor" href="#组件内的守卫" aria-label="Permalink to &quot;组件内的守卫&quot;">​</a></h1><blockquote><p>本节目标：理解“组件内的守卫”的核心思路，并能把它用于实际开发或面试表达。 最后，你可以在路由组件内直接定义路由导航守卫(传递给路由配置的)</p></blockquote><p><strong>可用的配置 API</strong> 你可以为路由组件添加以下配置： beforeRouteEnter beforeRouteUpdate beforeRouteLeave const UserDetails = { template: <code>...</code>, beforeRouteEnter(to, from) { // 在渲染该组件的对应路由被验证前调用 // 不能获取组件实例 <code>this</code> ！ // 因为当守卫执行时，组件实例还没被创建！ }, beforeRouteUpdate(to, from) { // 在当前路由改变，但是该组件被复用时调用 // 举例来说，对于一个带有动态参数的路径 <code>/users/:id</code>，在 <code>/users/1</code> 和 <code>/users/2</code> 之间跳转的时候， // 由于会渲染同样的 <code>UserDetails</code> 组件，因此组件实例会被复用。而这个钩子就会在这个情况下被调用。 // 因为在这种情况发生的时候，组件已经挂载好了，导航守卫可以访问组件实例 <code>this</code> }, beforeRouteLeave(to, from) { // 在导航离开渲染该组件的对应路由时调用 // 与 <code>beforeRouteUpdate</code> 一样，它可以访问组件实例 <code>this</code> }, }</p><p>beforeRouteEnter 守卫 不能 访问 this，因为守卫在导航确认前被调用，因此即将登场的新组件还没被创建。</p><p>不过，你可以通过传一个回调给 next 来访问组件实例。在导航被确认的时候执行回调，并且把组件实例作为回调方法的参数： beforeRouteEnter (to, from, next) { next(vm =&gt; { // 通过 <code>vm</code> 访问组件实例 }) }</p><p>注意 beforeRouteEnter 是支持给 next 传递回调的唯一守卫。对于 beforeRouteUpdate 和 beforeRouteLeave 来说，this 已经可用了，所以不支持 传递回调，因为没有必要了： beforeRouteUpdate (to, from) { // just use <code>this</code> this.name = to.params.name } 这个 离开守卫 通常用来预防用户在还未保存修改前突然离开。该导航可以通过返回 false 来取消。 beforeRouteLeave (to, from) { const answer = window.confirm(&#39;Do you really want to leave? you have unsaved changes!&#39;) if (!answer) return false }</p></div>',1)])])}const _=o(s,[["render",d]]);export{l as __pageData,_ as default};
